      return 48;
    case heif_chroma_interleaved_RRGGBBAA_BE:
    case heif_chroma_interleaved_RRGGBBAA_LE:
      return 64;
    default:
      return -1; // invalid channel/chroma specification
    }
  }
  else {
    return (get_bits_per_pixel(channel) + 7) & ~7;
  }
}


